struct SumAsyncStateMachine : IAsyncStateMachine
{
    public int state;                 // -1: start; 0 and 1: which await it stopped at
    public AsyncTaskMethodBuilder<int> builder;
    public int a, b;                  // local variables became fields
    public TaskAwaiter<int> awaiter;  // awaiter of the current await
